function PreviewPage({ day, setDay, reminded, setReminded, expanded, setExpanded, onBack }: { day: string; setDay: (day: string) => void; reminded: number[]; setReminded: (ids: number[]) => void; expanded: number[]; setExpanded: (ids: number[]) => void; onBack: () => void }) { const events = previewEvents.filter((event) => event.day === day); return <MobileScroll className="app-screen"><main className="preview-page screen-content"><header className="preview-header"><button className="back-button" aria-label="返回首页" onClick={onBack}><ArrowLeftIcon /></button><div><h1>直播预告</h1><p>精彩赛事 · 不容错过</p></div></header><div className="preview-illustration"><ClockIcon /></div><Carousel className="day-carousel" contentClassName="day-track" ariaLabel="日期选择">{previewDays.map((item) => <button key={item.id} className={item.id === day ? "day-chip active" : "day-chip"} onClick={() => setDay(item.id)}><b>{item.label}</b><span>{item.count}</span></button>)}</Carousel><section className="event-list">{events.length ? events.map((event) => <PreviewEvent key={event.id} event={event} reminded={reminded.includes(event.id)} onReminder={() => setReminded(reminded.includes(event.id) ? reminded.filter((id) => id !== event.id) : [...reminded, event.id])} expanded={expanded.includes(event.id)} onExpand={() => setExpanded(expanded.includes(event.id) ? expanded.filter((id) => id !== event.id) : [...expanded, event.id])} />) : <div className="no-events">当天暂无直播预告</div>}</section></main></MobileScroll>; }
